#!/bin/sh
# Generated by esquadro: makes the key an app's CI deploys with. The public
# half goes to deploy-keys/<app>.pub; the private one goes straight to the
# app repository's secrets, with the server's address and host key, and
# is never written anywhere else.
set -eu
app=$1 repo=$2 host=$3

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
ssh-keygen -q -t ed25519 -N "" -C "deploy $app" -f "$tmp/key"
gh secret set DEPLOY_SSH_KEY --repo "$repo" < "$tmp/key"
gh secret set DEPLOY_HOST --repo "$repo" --body "$host"
ssh-keyscan -t ed25519 "$host" 2>/dev/null | gh secret set DEPLOY_KNOWN_HOSTS --repo "$repo"
mkdir -p deploy-keys
cp "$tmp/key.pub" "deploy-keys/$app.pub"
echo "deploy-keys/$app.pub written, and $repo has its secrets: run task apply"
